export interface BurpEntry {
  id: number;
  statusCode: number;
  timestamp: number; // Raw timestamp
  relativeTime: number; // Seconds from start
  errorCount: number;
  timeoutCount: number;
}

export interface AttackStats {
  totalRequests: number;
  durationSeconds: number;
  averageRps: number;
  statusCodeCounts: Record<number, number>;
  totalErrors: number;
  totalTimeouts: number;
  startTime: number;
  endTime: number;
}

export interface AnalysisReport {
  summary: string;
  recommendations: string[];
  severity: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
}

import { BurpEntry, AttackStats } from '../types';

export const parseCSV = async (file: File): Promise<{ entries: BurpEntry[]; stats: AttackStats }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) {
        reject(new Error("Empty file"));
        return;
      }

      const lines = text.split(/\r?\n/);
      const entries: BurpEntry[] = [];

      // Column Mapping based on User Request:
      // A (0): Request Number
      // C (2): Status Code
      // D (3): Timestamp (13-digit Unix)
      // G (6): Error Count
      // H (7): Timeout Count

      let minTime = Infinity;
      let maxTime = -Infinity;

      // Skip header if it exists (heuristic: check if column 0 is a number)
      let startIndex = 0;
      const firstLineCols = lines[0].split(',').map(c => c.replace(/"/g, ''));
      if (isNaN(parseInt(firstLineCols[0]))) {
        startIndex = 1;
      }

      for (let i = startIndex; i < lines.length; i++) {
        const line = lines[i];
        if (!line.trim()) continue;

        // Simple CSV split (handling standard Burp export which usually doesn't have complex quoted commas in these specific columns)
        const cols = line.split(',').map(c => c.trim().replace(/"/g, ''));

        if (cols.length < 8) continue; // Ensure we have enough columns for 'H'

        const id = parseInt(cols[0]);
        const statusCode = parseInt(cols[2]);
        const timestamp = parseInt(cols[3]);
        const errorCount = parseInt(cols[6]) || 0;
        const timeoutCount = parseInt(cols[7]) || 0;

        if (!isNaN(id) && !isNaN(timestamp)) {
            if (timestamp < minTime) minTime = timestamp;
            if (timestamp > maxTime) maxTime = timestamp;

            entries.push({
                id,
                statusCode: isNaN(statusCode) ? 0 : statusCode,
                timestamp,
                relativeTime: 0, // Calculated after finding minTime
                errorCount,
                timeoutCount
            });
        }
      }

      if (entries.length === 0) {
        reject(new Error("No valid data found in CSV. Ensure columns match Burp default."));
        return;
      }

      // Calculate relative stats
      entries.sort((a, b) => a.timestamp - b.timestamp);

      // Recalculate min/max after sort to be sure
      minTime = entries[0].timestamp;
      maxTime = entries[entries.length - 1].timestamp;
      const durationSeconds = (maxTime - minTime) / 1000;

      entries.forEach(e => {
        e.relativeTime = (e.timestamp - minTime) / 1000;
      });

      const statusCodeCounts: Record<number, number> = {};
      let totalErrors = 0;
      let totalTimeouts = 0;

      entries.forEach(e => {
        statusCodeCounts[e.statusCode] = (statusCodeCounts[e.statusCode] || 0) + 1;
        totalErrors += e.errorCount;
        totalTimeouts += e.timeoutCount;
      });

      const stats: AttackStats = {
        totalRequests: entries.length,
        durationSeconds: durationSeconds > 0 ? durationSeconds : 1, // Avoid divide by zero
        averageRps: entries.length / (durationSeconds > 0 ? durationSeconds : 1),
        statusCodeCounts,
        totalErrors,
        totalTimeouts,
        startTime: minTime,
        endTime: maxTime
      };

      resolve({ entries, stats });
    };

    reader.onerror = () => reject(new Error("Failed to read file"));

    // Use ISO-8859-1 (Latin-1) to handle potential byte issues like 0xf1 gracefully
    reader.readAsText(file, 'ISO-8859-1');
  });
};

import { GoogleGenAI, Type } from "@google/genai";
import { AttackStats, BurpEntry, AnalysisReport } from "../types";

export const analyzeAttackData = async (entries: BurpEntry[], stats: AttackStats): Promise<AnalysisReport> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key not found");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Downsample data for prompt if too large
  const step = Math.ceil(entries.length / 50); // Take ~50 sample points
  const samples = entries.filter((_, i) => i % step === 0).map(e => ({
    time: e.relativeTime.toFixed(2),
    status: e.statusCode,
    err: e.errorCount,
    timeout: e.timeoutCount
  }));

  const prompt = `
  Analyze this Burp Suite Intruder attack log data for security insights regarding WAF behavior, Rate Limiting, and Throttling.

  **Summary Stats:**
  - Total Requests: ${stats.totalRequests}
  - Duration: ${stats.durationSeconds.toFixed(2)}s
  - Avg RPS: ${stats.averageRps.toFixed(2)}
  - Status Codes: ${JSON.stringify(stats.statusCodeCounts)}
  - Total Errors: ${stats.totalErrors}
  - Total Timeouts: ${stats.totalTimeouts}

  **Sample Data Points (Time in sec, Status, Errors, Timeouts):**
  ${JSON.stringify(samples)}

  Provide a JSON response with:
  1. "summary": A concise technical summary of the defensive behavior observed (e.g., "WAF started blocking at T+10s with 429s").
  2. "recommendations": A list of 3 specific offensive tuning recommendations (e.g., "Reduce threads to 5", "Add jitter").
  3. "severity": The level of aggressive blocking detected (LOW, MEDIUM, HIGH, CRITICAL).
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: { type: Type.STRING },
          recommendations: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          severity: { type: Type.STRING, enum: ["LOW", "MEDIUM", "HIGH", "CRITICAL"] }
        }
      }
    }
  });

  if (response.text) {
    return JSON.parse(response.text) as AnalysisReport;
  }

  throw new Error("Failed to generate analysis");
};

import React, { useCallback, useState } from 'react';
import { Upload, FileType, AlertTriangle } from 'lucide-react';

interface FileUploadProps {
  onFileLoaded: (file: File) => void;
  isLoading: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onFileLoaded, isLoading }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setIsDragging(true);
    } else if (e.type === 'dragleave') {
      setIsDragging(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
    setError(null);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      if (file.name.endsWith('.csv') || file.type.includes('csv') || file.type.includes('text')) {
        onFileLoaded(file);
      } else {
        setError("Invalid file type. Please upload a Burp Suite CSV export.");
      }
    }
  }, [onFileLoaded]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    e.preventDefault();
    setError(null);
    if (e.target.files && e.target.files[0]) {
       onFileLoaded(e.target.files[0]);
    }
  };

  return (
    <div className="w-full max-w-2xl mx-auto mt-20">
      <div
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
        className={`
          relative flex flex-col items-center justify-center w-full h-64 border-2 border-dashed rounded-lg transition-all duration-300
          ${isDragging 
            ? 'border-cyan-500 bg-cyan-950/20' 
            : 'border-slate-700 bg-slate-900 hover:border-slate-500 hover:bg-slate-800'}
        `}
      >
        <div className="flex flex-col items-center justify-center pt-5 pb-6">
            {isLoading ? (
                 <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-cyan-500 mb-4"></div>
            ) : (
                <Upload className={`w-12 h-12 mb-4 ${isDragging ? 'text-cyan-400' : 'text-slate-400'}`} />
            )}
          <p className="mb-2 text-sm text-slate-300">
            <span className="font-semibold">Click to upload</span> or drag and drop
          </p>
          <p className="text-xs text-slate-500">Burp Suite Intruder CSV Export</p>
        </div>
        <input 
            id="dropzone-file" 
            type="file" 
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            onChange={handleChange}
            disabled={isLoading}
        />
      </div>
      {error && (
        <div className="mt-4 p-4 bg-red-900/20 border border-red-800 rounded flex items-center gap-2 text-red-200">
          <AlertTriangle className="w-5 h-5" />
          <span>{error}</span>
        </div>
      )}
    </div>
  );
};

import React from 'react';

interface RpsGaugeProps {
  value: number;
}

export const RpsGauge: React.FC<RpsGaugeProps> = ({ value }) => {
  // Simple SVG Gauge
  const radius = 80;
  const stroke = 12;
  const normalizedValue = Math.min(Math.max(value, 0), 100); // Cap visual at 100 for scale
  const circumference = radius * 2 * Math.PI;
  const offset = circumference - (normalizedValue / 200) * circumference; // Half circle

  // Color logic
  let color = "text-emerald-500";
  if (value > 20) color = "text-yellow-500";
  if (value > 50) color = "text-orange-500";
  if (value > 80) color = "text-red-500";

  return (
    <div className="relative flex flex-col items-center justify-center h-full">
      <div className="relative w-48 h-24 overflow-hidden mb-2">
        <svg
          className="w-48 h-48 transform origin-center rotate-[0deg]"
          viewBox="0 0 200 200"
        >
          {/* Background Track */}
          <circle
            className="text-slate-700"
            strokeWidth={stroke}
            stroke="currentColor"
            fill="transparent"
            r={radius}
            cx="100"
            cy="100"
            strokeDasharray={`${circumference} ${circumference}`}
            strokeDashoffset={circumference / 2}
            transform="rotate(180 100 100)"
          />
          {/* Progress */}
          <circle
            className={`${color} transition-all duration-1000 ease-out`}
            strokeWidth={stroke}
            strokeLinecap="round"
            stroke="currentColor"
            fill="transparent"
            r={radius}
            cx="100"
            cy="100"
            strokeDasharray={`${circumference} ${circumference}`}
            strokeDashoffset={offset}
            transform="rotate(180 100 100)"
          />
        </svg>
      </div>
      <div className="absolute top-16 flex flex-col items-center">
        <span className="text-4xl font-bold text-slate-100">{value.toFixed(1)}</span>
        <span className="text-xs text-slate-400 uppercase tracking-widest">Avg RPS</span>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import {
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  XAxis,
  YAxis,
  ZAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { BurpEntry } from '../types';

interface TimeSeriesChartProps {
  data: BurpEntry[];
}

export const TimeSeriesChart: React.FC<TimeSeriesChartProps> = ({ data }) => {
  // Aggregate data into 1-second buckets for performance and readability
  const chartData = useMemo(() => {
    const buckets: Record<number, Record<string, number>> = {};
    const maxTime = Math.ceil(data[data.length - 1]?.relativeTime || 0);

    for (let i = 0; i <= maxTime; i++) {
        buckets[i] = { time: i };
    }

    data.forEach((entry) => {
      const second = Math.floor(entry.relativeTime);
      const codeKey = `status_${entry.statusCode}`;
      if (!buckets[second]) buckets[second] = { time: second };
      buckets[second][codeKey] = (buckets[second][codeKey] || 0) + 1;
    });

    // Flatten for Recharts
    // Actually, for a scatter plot of status codes, let's look at the "Breaking Point".
    // A Scatter plot with Time (X) and Status Code (Y) is often very revealing for WAFs.
    // Or a Line chart of counts per second. 
    // The prompt asks for "Plot Status Codes over time to identify the Breaking Point". 
    // A Multi-Line chart of Counts per Status Code per Second is best.

    return Object.values(buckets).sort((a, b) => a.time - b.time);
  }, [data]);

  const uniqueStatusCodes = useMemo(() => {
      const codes = new Set<number>();
      data.forEach(d => codes.add(d.statusCode));
      return Array.from(codes).sort();
  }, [data]);

  const getColor = (code: number) => {
      if (code >= 200 && code < 300) return '#10b981'; // Green
      if (code >= 300 && code < 400) return '#3b82f6'; // Blue
      if (code === 429) return '#f59e0b'; // Orange/Yellow (Rate Limit)
      if (code === 403) return '#ef4444'; // Red (Forbidden)
      if (code >= 500) return '#a855f7'; // Purple (Server Error)
      return '#64748b'; // Slate
  };

  return (
    <div className="w-full h-full min-h-[300px]">
      <ResponsiveContainer width="100%" height="100%">
        <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
          <XAxis 
            dataKey="relativeTime" 
            type="number" 
            name="Time" 
            unit="s" 
            stroke="#94a3b8" 
            domain={['dataMin', 'dataMax']}
          />
          <YAxis 
            dataKey="statusCode" 
            type="number" 
            name="Status" 
            stroke="#94a3b8" 
            domain={['auto', 'auto']}
            allowDecimals={false}
          />
          <ZAxis type="number" dataKey="count" range={[50, 400]} name="Volume" />
          <Tooltip 
            cursor={{ strokeDasharray: '3 3' }} 
            contentStyle={{ backgroundColor: '#1e293b', borderColor: '#475569', color: '#f1f5f9' }}
          />
          <Legend />
          {/* We plot raw entries as scatters, but grouped by second would be cleaner for lines. 
              Let's stick to the prompt's "Breaking Point" - seeing individual request drift is cool. 
              Actually, for high volume, Scatter is heavy. Let's do a grouped Scatter where Y=Status, X=Time, Z=Count (size).
          */}
           <Scatter name="Requests" data={
               // Transform for Scatter: X=TimeBucket, Y=Status, Z=Count
               Object.values(chartData).flatMap(bucket => {
                   return Object.keys(bucket).filter(k => k.startsWith('status_')).map(k => ({
                       relativeTime: bucket.time,
                       statusCode: parseInt(k.replace('status_', '')),
                       count: bucket[k]
                   }))
               })
           } fill="#8884d8">
              {uniqueStatusCodes.map(code => (
                  // This is a bit of a hack in Recharts to color by cell, usually done via Cell component
                  // but we are mapping data. Let's just let the Scatter use a shape or color function.
                  // Simpler: Just one Scatter, color depends on the point? Recharts Scatter doesn't support dynamic fill easily per point without Cell.
                  // We will render multiple Scatters, one per status code.
                  null
              ))}
           </Scatter>
           {uniqueStatusCodes.map(code => (
               <Scatter 
                    key={code} 
                    name={`Status ${code}`} 
                    data={
                        Object.values(chartData).flatMap(bucket => {
                            const key = `status_${code}`;
                            if (!bucket[key]) return [];
                            return [{
                                relativeTime: bucket.time,
                                statusCode: code,
                                count: bucket[key]
                            }];
                        })
                    } 
                    fill={getColor(code)} 
                />
           ))}
        </ScatterChart>
      </ResponsiveContainer>
    </div>
  );
};

import React from 'react';
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Cell
} from 'recharts';
import { AttackStats } from '../types';

interface StatsBarChartProps {
  stats: AttackStats;
}

export const StatsBarChart: React.FC<StatsBarChartProps> = ({ stats }) => {
  const data = [
    { name: 'Timeouts (H)', value: stats.totalTimeouts, color: '#f59e0b' },
    { name: 'Errors (G)', value: stats.totalErrors, color: '#ef4444' },
    { name: 'Total Reqs', value: stats.totalRequests, color: '#3b82f6' },
  ];

  return (
    <div className="w-full h-full min-h-[200px]">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={data} layout="vertical" margin={{ top: 5, right: 30, left: 40, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#334155" horizontal={false} />
          <XAxis type="number" stroke="#94a3b8" />
          <YAxis dataKey="name" type="category" stroke="#94a3b8" width={80} />
          <Tooltip 
            cursor={{fill: '#334155', opacity: 0.2}}
            contentStyle={{ backgroundColor: '#1e293b', borderColor: '#475569', color: '#f1f5f9' }}
          />
          <Bar dataKey="value" radius={[0, 4, 4, 0]} barSize={30}>
            {data.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.color} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

import React, { useState } from 'react';
import { FileUpload } from './components/FileUpload';
import { RpsGauge } from './components/RpsGauge';
import { TimeSeriesChart } from './components/TimeSeriesChart';
import { StatsBarChart } from './components/StatsBarChart';
import { parseCSV } from './services/parser';
import { analyzeAttackData } from './services/geminiService';
import { BurpEntry, AttackStats, AnalysisReport } from './types';
import { Shield, Activity, Clock, AlertTriangle, Cpu, Terminal, Lock } from 'lucide-react';

export default function App() {
  const [entries, setEntries] = useState<BurpEntry[] | null>(null);
  const [stats, setStats] = useState<AttackStats | null>(null);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [report, setReport] = useState<AnalysisReport | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleFile = async (file: File) => {
    setLoading(true);
    setError(null);
    setReport(null);
    try {
      const { entries, stats } = await parseCSV(file);
      setEntries(entries);
      setStats(stats);
    } catch (e: any) {
      setError(e.message || "Failed to parse file");
    } finally {
      setLoading(false);
    }
  };

  const runAnalysis = async () => {
    if (!entries || !stats) return;
    setAnalyzing(true);
    try {
      const result = await analyzeAttackData(entries, stats);
      setReport(result);
    } catch (e) {
      setError("AI Analysis failed. Check API Key or try again.");
    } finally {
      setAnalyzing(false);
    }
  };

  const reset = () => {
    setEntries(null);
    setStats(null);
    setReport(null);
    setError(null);
  }

  return (
    <div className="flex flex-col h-full w-full overflow-hidden">
      {/* Header */}
      <header className="flex-none h-16 bg-slate-900 border-b border-slate-800 flex items-center px-6 justify-between shadow-md z-10">
        <div className="flex items-center gap-3">
          <Shield className="w-8 h-8 text-cyan-500" />
          <h1 className="text-xl font-bold tracking-tight text-slate-100">
            BURP<span className="text-cyan-500">INT</span>RUDER<span className="text-slate-500 text-sm ml-2 font-normal">DATA ANALYST</span>
          </h1>
        </div>
        {stats && (
            <button 
                onClick={reset}
                className="text-sm text-slate-400 hover:text-white transition-colors"
            >
                Upload New File
            </button>
        )}
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto overflow-x-hidden bg-slate-950 p-6">

        {/* State: No Data */}
        {!stats && (
          <div className="h-full flex flex-col items-center justify-center -mt-16">
            <div className="text-center mb-8">
                <h2 className="text-3xl font-bold text-slate-100 mb-2">Initialize Analysis Protocol</h2>
                <p className="text-slate-400 max-w-md mx-auto">
                    Upload your Burp Suite Intruder CSV export to visualize rate limiting, throttling behavior, and WAF responses.
                </p>
            </div>
            <FileUpload onFileLoaded={handleFile} isLoading={loading} />
            {error && (
                <div className="mt-6 p-4 bg-red-900/30 border border-red-800 rounded text-red-300 max-w-xl w-full text-center">
                    {error}
                </div>
            )}
          </div>
        )}

        {/* State: Dashboard */}
        {entries && stats && (
          <div className="max-w-7xl mx-auto space-y-6">

            {/* Top Stats Row */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              {/* Duration Card */}
              <div className="bg-slate-900 border border-slate-800 rounded-lg p-4 shadow-sm flex items-center justify-between">
                <div>
                  <p className="text-slate-500 text-xs font-semibold uppercase tracking-wider">Total Duration</p>
                  <p className="text-2xl font-bold text-slate-100">{stats.durationSeconds.toFixed(2)}s</p>
                </div>
                <div className="p-3 bg-slate-800 rounded-full">
                  <Clock className="w-6 h-6 text-cyan-500" />
                </div>
              </div>

              {/* Request Count Card */}
              <div className="bg-slate-900 border border-slate-800 rounded-lg p-4 shadow-sm flex items-center justify-between">
                <div>
                  <p className="text-slate-500 text-xs font-semibold uppercase tracking-wider">Total Requests</p>
                  <p className="text-2xl font-bold text-slate-100">{stats.totalRequests.toLocaleString()}</p>
                </div>
                <div className="p-3 bg-slate-800 rounded-full">
                  <Activity className="w-6 h-6 text-indigo-500" />
                </div>
              </div>

               {/* Error Count Card */}
               <div className="bg-slate-900 border border-slate-800 rounded-lg p-4 shadow-sm flex items-center justify-between">
                <div>
                  <p className="text-slate-500 text-xs font-semibold uppercase tracking-wider">Errors / Timeouts</p>
                  <p className="text-2xl font-bold text-slate-100">{stats.totalErrors} <span className="text-slate-600">/</span> {stats.totalTimeouts}</p>
                </div>
                <div className="p-3 bg-slate-800 rounded-full">
                  <AlertTriangle className="w-6 h-6 text-orange-500" />
                </div>
              </div>

              {/* AI Action Card */}
              <div className="bg-gradient-to-br from-indigo-900 to-slate-900 border border-indigo-700 rounded-lg p-1 shadow-sm flex items-center justify-center">
                 {!report ? (
                    <button 
                        onClick={runAnalysis} 
                        disabled={analyzing}
                        className="w-full h-full flex flex-col items-center justify-center hover:bg-white/5 transition-colors rounded cursor-pointer group disabled:opacity-50"
                    >
                        {analyzing ? (
                             <div className="animate-spin h-6 w-6 border-2 border-indigo-400 rounded-full border-t-transparent mb-2"></div>
                        ) : (
                            <Cpu className="w-8 h-8 text-indigo-400 mb-1 group-hover:scale-110 transition-transform" />
                        )}
                        <span className="text-indigo-200 font-semibold text-sm">
                            {analyzing ? 'Analyzing Pattern...' : 'Run AI Security Analysis'}
                        </span>
                    </button>
                 ) : (
                    <div className="flex flex-col items-center justify-center">
                        <div className={`text-lg font-bold ${report.severity === 'CRITICAL' || report.severity === 'HIGH' ? 'text-red-400' : 'text-emerald-400'}`}>
