import { BurpEntry, AttackStats } from '../types';

export const parseCSV = async (file: File): Promise<{ entries: BurpEntry[]; stats: AttackStats }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) {
        reject(new Error("Empty file"));
        return;
      }

      const lines = text.split(/\r?\n/);
      let entries: BurpEntry[] = [];

      // Column Mapping:
      // A (0): Request Number
      // C (2): Status Code
      // D (3): Timestamp (13-digit Unix)
      // G (6): Error
      // H (7): Timeout

      // Skip header logic
      let startIndex = 0;
      const firstLineCols = lines[0].split(',').map(c => c.replace(/"/g, ''));
      if (isNaN(parseInt(firstLineCols[0]))) {
        startIndex = 1;
      }

      for (let i = startIndex; i < lines.length; i++) {
        const line = lines[i];
        if (!line.trim()) continue;

        const cols = line.split(',').map(c => c.trim().replace(/"/g, ''));

        if (cols.length < 4) continue; // Need at least up to timestamp

        const id = parseInt(cols[0]);
        const statusCode = parseInt(cols[2]);
        const timestamp = parseInt(cols[3]);

        // Logic: Count as error/timeout if the value is NOT "false" (and not empty/zero representation if applicable, but user said "diferente de FALSE")
        const rawError = cols[6] ? cols[6].toLowerCase() : 'false';
        const rawTimeout = cols[7] ? cols[7].toLowerCase() : 'false';

        // Check strictly against 'false'. Often empty strings in CSVs might mean false too, but let's stick to "different from false".
        // We also treat '0' as false just in case, but primary request is 'not false'.
        const isError = rawError !== 'false' && rawError !== ''; 
        const isTimeout = rawTimeout !== 'false' && rawTimeout !== '';

        const errorCount = isError ? 1 : 0;
        const timeoutCount = isTimeout ? 1 : 0;

        // Filter out 0 or extremely low timestamps which ruin the duration calculation
        if (!isNaN(id) && !isNaN(timestamp) && timestamp > 1000000000) { 
            entries.push({
                id,
                statusCode: isNaN(statusCode) ? 0 : statusCode,
                timestamp,
                relativeTime: 0,
                errorCount,
                timeoutCount
            });
        }
      }

      if (entries.length === 0) {
        reject(new Error("No valid data found in CSV. Ensure columns match Burp default."));
        return;
      }

      // Sort by timestamp
      entries.sort((a, b) => a.timestamp - b.timestamp);

      const minTime = entries[0].timestamp;
      const maxTime = entries[entries.length - 1].timestamp;
      const durationSeconds = (maxTime - minTime) / 1000;

      // Calculate relative times
      entries.forEach(e => {
        e.relativeTime = (e.timestamp - minTime) / 1000;
      });

      const statusCodeCounts: Record<number, number> = {};
      let totalErrors = 0;
      let totalTimeouts = 0;

      entries.forEach(e => {
        statusCodeCounts[e.statusCode] = (statusCodeCounts[e.statusCode] || 0) + 1;
        totalErrors += e.errorCount;
        totalTimeouts += e.timeoutCount;
      });

      const stats: AttackStats = {
        totalRequests: entries.length,
        durationSeconds: durationSeconds > 0 ? durationSeconds : 0.1,
        averageRps: entries.length / (durationSeconds > 0 ? durationSeconds : 1),
        statusCodeCounts,
        totalErrors,
        totalTimeouts,
        startTime: minTime,
        endTime: maxTime
      };

      resolve({ entries, stats });
    };

    reader.onerror = () => reject(new Error("Failed to read file"));
    reader.readAsText(file, 'ISO-8859-1');
  });
};

import { GoogleGenAI, Type } from "@google/genai";
import { AttackStats, BurpEntry, AnalysisReport } from "../types";

export const analyzeAttackData = async (entries: BurpEntry[], stats: AttackStats): Promise<AnalysisReport> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key not found");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Downsample data for prompt if too large
  const step = Math.ceil(entries.length / 50); // Take ~50 sample points
  const samples = entries.filter((_, i) => i % step === 0).map(e => ({
    time: e.relativeTime.toFixed(2),
    status: e.statusCode,
    err: e.errorCount,
    timeout: e.timeoutCount
  }));

  const prompt = `
  Você é um Especialista em Segurança Ofensiva e Analista Sênior. Analise estes logs do Burp Suite Intruder para identificar comportamentos de WAF, Rate Limiting e Throttling.

  **Estatísticas do Ataque:**
  - Total de Requisições: ${stats.totalRequests}
  - Duração: ${stats.durationSeconds.toFixed(2)}s
  - RPS Médio: ${stats.averageRps.toFixed(2)}
  - Códigos de Status: ${JSON.stringify(stats.statusCodeCounts)}
  - Total de Erros: ${stats.totalErrors}
  - Total de Timeouts: ${stats.totalTimeouts}

  **Amostra de Dados (Tempo seg, Status, Erros, Timeouts):**
  ${JSON.stringify(samples)}

  Forneça uma resposta JSON com:
  1. "summary": Um resumo técnico conciso em PORTUGUÊS DO BRASIL sobre o comportamento defensivo observado (ex: "WAF começou a bloquear em T+10s com 429s").
  2. "recommendations": Uma lista de 3 recomendações ofensivas específicas em PORTUGUÊS DO BRASIL (ex: "Reduzir threads para 5", "Adicionar jitter").
  3. "severity": O nível de bloqueio agressivo detectado (LOW, MEDIUM, HIGH, CRITICAL).
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: { type: Type.STRING },
          recommendations: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          severity: { type: Type.STRING, enum: ["LOW", "MEDIUM", "HIGH", "CRITICAL"] }
        }
      }
    }
  });

  if (response.text) {
    return JSON.parse(response.text) as AnalysisReport;
  }

  throw new Error("Failed to generate analysis");
};

import React, { useState } from 'react';
import { FileUpload } from './components/FileUpload';
