import { Shield, Activity, Clock, AlertTriangle, Cpu, Terminal, Lock } from 'lucide-react';

export default function App() {
  const [entries, setEntries] = useState<BurpEntry[] | null>(null);
  const [stats, setStats] = useState<AttackStats | null>(null);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [report, setReport] = useState<AnalysisReport | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleFile = async (file: File) => {
    setLoading(true);
    setError(null);
    setReport(null);
    try {
      const { entries, stats } = await parseCSV(file);
      setEntries(entries);
      setStats(stats);
    } catch (e: any) {
      setError(e.message || "Failed to parse file");
    } finally {
      setLoading(false);
    }
  };

  const runAnalysis = async () => {
    if (!entries || !stats) return;
    setAnalyzing(true);
    try {
      const result = await analyzeAttackData(entries, stats);
      setReport(result);
    } catch (e) {
      setError("AI Analysis failed. Check API Key or try again.");
    } finally {
      setAnalyzing(false);
    }
  };

  const reset = () => {
    setEntries(null);
    setStats(null);
    setReport(null);
    setError(null);
  }

