          </h1>
        </div>
        {stats && (
            <button 
                onClick={reset}
                className="text-sm text-slate-400 hover:text-white transition-colors"
            >
                Upload New File
            </button>
        )}
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto overflow-x-hidden bg-slate-950 p-6">

        {/* State: No Data */}
        {!stats && (
          <div className="h-full flex flex-col items-center justify-center -mt-16">
            <div className="text-center mb-8">
                <h2 className="text-3xl font-bold text-slate-100 mb-2">Initialize Analysis Protocol</h2>
