export interface BurpEntry {
  id: number;
  statusCode: number;
  timestamp: number; // Raw timestamp
  relativeTime: number; // Seconds from start
  latency: number; // Response time in ms
  errorCount: number;
  timeoutCount: number;
}

export interface AttackStats {
  totalRequests: number;
  durationSeconds: number;
  averageRps: number;
  statusCodeCounts: Record<number, number>;
  totalErrors: number;
  totalTimeouts: number;
  startTime: number;
  endTime: number;
}

export interface AnalysisReport {
  summary: string;
  recommendations: string[];
  severity: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
}

import { BurpEntry, AttackStats } from '../types';

export const parseCSV = async (file: File): Promise<{ entries: BurpEntry[]; stats: AttackStats }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) {
        reject(new Error("Arquivo vazio"));
        return;
      }

      const lines = text.split(/\r?\n/);
      let entries: BurpEntry[] = [];

      // Heuristic Column Mapping based on previous interactions and standard formats
      // A (0): Request Number
      // C (2): Status Code
      // D (3): Timestamp (13-digit Unix)
      // E (4): Latency / Timer (Assumed based on user request for Latency chart)
      // G (6): Error
      // H (7): Timeout

      let startIndex = 0;
      const firstLineCols = lines[0].split(',').map(c => c.replace(/"/g, ''));
      if (isNaN(parseInt(firstLineCols[0]))) {
        startIndex = 1;
      }

      for (let i = startIndex; i < lines.length; i++) {
        const line = lines[i];
        if (!line.trim()) continue;

        const cols = line.split(',').map(c => c.trim().replace(/"/g, ''));

        if (cols.length < 4) continue;

        const id = parseInt(cols[0]);
        const statusCode = parseInt(cols[2]);
        const timestamp = parseInt(cols[3]);

        // Attempt to parse latency from column 4 (E) or default to 0
        let latency = parseInt(cols[4]);
        if (isNaN(latency)) latency = 0;

        // Error/Timeout Logic (Not 'false' = 1)
        const rawError = cols[6] ? cols[6].toLowerCase() : 'false';
        const rawTimeout = cols[7] ? cols[7].toLowerCase() : 'false';
        const isError = rawError !== 'false' && rawError !== ''; 
        const isTimeout = rawTimeout !== 'false' && rawTimeout !== '';

        const errorCount = isError ? 1 : 0;
        const timeoutCount = isTimeout ? 1 : 0;

        // Filter valid rows
        if (!isNaN(id) && !isNaN(timestamp) && timestamp > 1000000000) { 
            entries.push({
                id,
                statusCode: isNaN(statusCode) ? 0 : statusCode,
                timestamp,
                relativeTime: 0,
                latency, 
                errorCount,
                timeoutCount
            });
        }
      }

      if (entries.length === 0) {
        reject(new Error("Nenhum dado válido encontrado. Verifique se o CSV é do Burp Intruder."));
        return;
      }

      // Sort by timestamp
      entries.sort((a, b) => a.timestamp - b.timestamp);

      const minTime = entries[0].timestamp;
      const maxTime = entries[entries.length - 1].timestamp;
      const durationSeconds = (maxTime - minTime) / 1000;

      // Calculate relative times
      entries.forEach(e => {
        e.relativeTime = (e.timestamp - minTime) / 1000;
      });

      const statusCodeCounts: Record<number, number> = {};
      let totalErrors = 0;
      let totalTimeouts = 0;

      entries.forEach(e => {
        statusCodeCounts[e.statusCode] = (statusCodeCounts[e.statusCode] || 0) + 1;
        totalErrors += e.errorCount;
        totalTimeouts += e.timeoutCount;
      });

      const stats: AttackStats = {
        totalRequests: entries.length,
        durationSeconds: durationSeconds > 0 ? durationSeconds : 0.1,
        averageRps: entries.length / (durationSeconds > 0 ? durationSeconds : 1),
        statusCodeCounts,
        totalErrors,
        totalTimeouts,
        startTime: minTime,
        endTime: maxTime
      };

      resolve({ entries, stats });
    };

    reader.onerror = () => reject(new Error("Falha ao ler o arquivo"));
    reader.readAsText(file, 'ISO-8859-1');
  });
};

import React from 'react';

interface RpsGaugeProps {
  value: number;
}

export const RpsGauge: React.FC<RpsGaugeProps> = ({ value }) => {
  // Config
  const maxVal = Math.max(100, Math.ceil(value / 100) * 100); // Dynamic max
  const percentage = Math.min(value / maxVal, 1);
  const rotation = -90 + (percentage * 180); // -90deg to 90deg (semicircle)

  // Color logic
  let colorClass = "text-emerald-500";
  let strokeColor = "#10b981";
  if (value > 20) { colorClass = "text-yellow-500"; strokeColor = "#eab308"; }
  if (value > 50) { colorClass = "text-orange-500"; strokeColor = "#f97316"; }
  if (value > 100) { colorClass = "text-red-500"; strokeColor = "#ef4444"; }

  return (
    <div className="relative flex flex-col items-center justify-center h-full w-full">
      {/* Gauge Container */}
      <div className="relative w-64 h-32 overflow-hidden flex items-end justify-center">

        {/* Background Arc */}
        <div className="absolute w-56 h-56 rounded-full border-[12px] border-slate-800" style={{top: 0}}></div>

        {/* Needle Wrapper (Rotate this) */}
        <div 
            className="absolute bottom-0 w-full flex justify-center origin-bottom transition-transform duration-1000 ease-out"
            style={{ 
                transform: `rotate(${rotation}deg)`,
                height: '100%' // Ensure pivot is correct relative to container
            }}
        >
             {/* The Needle */}
             <div className="w-1 h-[112px] bg-slate-200 rounded-t-full shadow-lg relative -top-[0px]" style={{ transformOrigin: 'bottom center' }}></div>
        </div>

        {/* Pivot Point */}
        <div className="absolute bottom-[-10px] w-4 h-4 bg-slate-200 rounded-full z-10"></div>

        {/* Active Arc (SVG Overlay for gradient/color bar if needed, but simple needle is cleaner for "speedometer" feel) */}
        {/* Let's try a simple SVG for the colored track */}
        <svg className="absolute top-0 left-0 w-full h-full" viewBox="0 0 256 128" preserveAspectRatio="none">
             <path d="M 28 128 A 100 100 0 0 1 228 128" fill="none" stroke={strokeColor} strokeWidth="12" strokeDasharray="314" strokeDashoffset={314 - (314 * percentage)} strokeLinecap="round" className="transition-all duration-1000 ease-out opacity-80" />
        </svg>

      </div>

      {/* Value Text */}
      <div className="flex flex-col items-center mt-4">
        <span className={`text-5xl font-bold ${colorClass} tabular-nums`}>{value.toFixed(1)}</span>
        <span className="text-sm text-slate-400 font-medium tracking-widest mt-1">REQ / SEGUNDO</span>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import {
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  XAxis,
  YAxis,
  ZAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { BurpEntry } from '../types';

interface TimeSeriesChartProps {
  data: BurpEntry[];
}

export const TimeSeriesChart: React.FC<TimeSeriesChartProps> = ({ data }) => {
  // Determine if we have valid latency data (check if any latency > 0)
  const hasLatency = useMemo(() => data.some(d => d.latency > 0), [data]);

  const uniqueStatusCodes = useMemo(() => {
      const codes = new Set<number>();
      data.forEach(d => codes.add(d.statusCode));
      return Array.from(codes).sort();
  }, [data]);

  const getColor = (code: number) => {
      if (code >= 200 && code < 300) return '#10b981'; // Green
      if (code >= 300 && code < 400) return '#3b82f6'; // Blue
      if (code === 429) return '#f59e0b'; // Orange/Yellow
      if (code === 403) return '#ef4444'; // Red
      if (code >= 500) return '#a855f7'; // Purple
      return '#64748b'; // Slate
  };

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      return (
        <div className="bg-slate-900 border border-slate-700 p-3 rounded shadow-xl text-xs">
          <p className="text-slate-400 mb-1">{new Date(data.timestamp).toLocaleTimeString('pt-BR')}</p>
          <p className="font-bold text-slate-200">ID: {data.id}</p>
          <p className="font-bold" style={{ color: getColor(data.statusCode) }}>Status: {data.statusCode}</p>
          {hasLatency && <p className="text-slate-300">Latência: {data.latency} ms</p>}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="w-full h-full min-h-[300px]">
      <ResponsiveContainer width="100%" height="100%">
        <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 10 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.5} />

          <XAxis 
            dataKey="timestamp" 
            type="number" 
            name="Horário" 
            domain={['dataMin', 'dataMax']}
            tickFormatter={(unixTime) => new Date(unixTime).toLocaleTimeString('pt-BR')}
            stroke="#94a3b8" 
            tick={{fontSize: 12}}
          />

          <YAxis 
            dataKey={hasLatency ? "latency" : "statusCode"}
            type="number" 
            name={hasLatency ? "Latência (ms)" : "Status Code"}
            stroke="#94a3b8" 
            tick={{fontSize: 12}}
            label={{ 
                value: hasLatency ? 'Tempo (ms)' : 'Código Status', 
                angle: -90, 
                position: 'insideLeft',
                style: { fill: '#64748b', fontSize: 12 }
            }}
          />

          <Tooltip content={<CustomTooltip />} />
          <Legend wrapperStyle={{ fontSize: '12px', paddingTop: '10px' }} />

          {uniqueStatusCodes.map(code => (
             <Scatter 
                key={code} 
                name={`Status ${code}`} 
                data={data.filter(d => d.statusCode === code)}
                fill={getColor(code)}
                shape="circle"
             />
          ))}
        </ScatterChart>
      </ResponsiveContainer>
    </div>
  );
};

